CREATE TABLE workspaces (id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE actors (id TEXT PRIMARY KEY, workspaceId TEXT NOT NULL REFERENCES workspaces(id), kind TEXT NOT NULL, name TEXT NOT NULL, ownerId TEXT NOT NULL, lastSeen INTEGER);
CREATE TABLE work (id TEXT PRIMARY KEY, workspaceId TEXT NOT NULL REFERENCES workspaces(id), createdBy TEXT NOT NULL REFERENCES actors(id), ownerId TEXT REFERENCES actors(id), title TEXT NOT NULL, objective TEXT NOT NULL, acceptanceCriteria TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN ('low','normal','high','urgent')), visibility TEXT NOT NULL DEFAULT 'private', lifecycle TEXT NOT NULL CHECK(lifecycle IN ('open','blocked','completed','cancelled')), revision INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX work_updated ON work(updatedAt);
CREATE TABLE source_refs (id TEXT PRIMARY KEY, workId TEXT NOT NULL REFERENCES work(id), system TEXT NOT NULL, url TEXT NOT NULL);
CREATE TABLE assignments (id TEXT PRIMARY KEY, workId TEXT NOT NULL REFERENCES work(id), recipientId TEXT NOT NULL REFERENCES actors(id), state TEXT NOT NULL CHECK(state IN ('proposed','accepted','declined','withdrawn')), decidedAt INTEGER);
CREATE UNIQUE INDEX assignment_work ON assignments(workId);
CREATE TABLE approvals (id TEXT PRIMARY KEY, workId TEXT NOT NULL REFERENCES work(id), approverId TEXT NOT NULL REFERENCES actors(id), adapter TEXT NOT NULL CHECK(adapter='stub'), revision INTEGER NOT NULL, snapshot TEXT NOT NULL, createdAt INTEGER NOT NULL);
CREATE TABLE runs (id TEXT PRIMARY KEY, workId TEXT NOT NULL REFERENCES work(id), approvalId TEXT NOT NULL REFERENCES approvals(id), ownerId TEXT NOT NULL REFERENCES actors(id), state TEXT NOT NULL CHECK(state IN ('queued','claimed','running','awaiting_review','succeeded','changes_requested','failed','cancelled')), workerId TEXT REFERENCES actors(id), claimToken TEXT, leaseExpiresAt INTEGER, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, summary TEXT, artifact TEXT, failure TEXT);
CREATE UNIQUE INDEX one_active_run ON runs(workId) WHERE state IN ('queued','claimed','running','awaiting_review');
CREATE INDEX run_queue ON runs(state,createdAt);
CREATE TABLE attention (id TEXT PRIMARY KEY, workId TEXT NOT NULL REFERENCES work(id), kind TEXT NOT NULL, createdAt INTEGER NOT NULL, resolvedAt INTEGER);
CREATE UNIQUE INDEX one_attention_kind ON attention(workId,kind) WHERE resolvedAt IS NULL;
CREATE TABLE events (id TEXT PRIMARY KEY, workId TEXT NOT NULL REFERENCES work(id), actorId TEXT NOT NULL REFERENCES actors(id), type TEXT NOT NULL, message TEXT NOT NULL, data TEXT NOT NULL, "references" TEXT NOT NULL, createdAt INTEGER NOT NULL);
CREATE INDEX events_work ON events(workId,createdAt);
CREATE TRIGGER events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT,'events are append-only'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT,'events are append-only'); END;
CREATE TABLE credentials (id TEXT PRIMARY KEY, actorId TEXT NOT NULL REFERENCES actors(id), hash TEXT NOT NULL UNIQUE, scope TEXT NOT NULL, createdAt INTEGER NOT NULL, expiresAt INTEGER, revokedAt INTEGER);
CREATE TABLE idempotency (key TEXT PRIMARY KEY, fingerprint TEXT NOT NULL, resourceId TEXT NOT NULL);
